 31   let equal = Object.keys(old).length === keys.length;
 32   const result: Record<string, unknown> = Array.isArray(after) ? [] as unknown as Record<string, unknown> : {};
 33   for (const key of keys) { result[key] = shareEqual(old[key], next[key]); if (!Object.is(result[key], old[key]) || !(key in old)) equal = false; }
 34   return equal ? before : result as T;
 35 }
 36 class Models<T> {
 37   private entries = new Map<string, Atom<T | undefined>>();
 38   get(id: string) {
 39     let entry = this.entries.get(id);
 40     if (!entry) { entry = atom<T | undefined>(`mapping:${id}`, undefined); this.entries.set(id, entry); }
 41     return entry;
 42   }
 43   publish(values: Map<string, T>) {
 44     for (const [id, entry] of this.entries) if (!values.has(id)) entry.set(undefined);
 45     for (const [id, value] of values) { const entry = this.get(id); entry.set(shareEqual(entry.get(), value)); }
 46   }
 47 }
