  2 import { type Editor, type TLShapePartial } from 'tldraw';
  3 import { flattenGrid, resolveScene } from '../../../../domain/core/diagrams/lineGrid';
  4 import { selectedDiagramIds } from '../../../../domain/mapping/selection/selectionState';
  5 import { updateDisplayGeometry } from '../../../../domain/mapping/workspace/displayModel';
  6 import type { MappingDocumentController, DiagramOperation } from '../../../../domain/mapping/workspace/mappingDocumentController';
  7 import { DEFAULT_CELL, mappingShapeId, projectMappingShapes } from './shapeProjection';
  8 import type { MappingShape } from './MappingShapeUtil';
  9 
 10 /** The Editor owns live geometry and undo. The domain controller supplies semantic
 11  * commands and an immutable checkpoint archive for persistence/headless proposals.
 12  * No controller writes occur on camera or pointer-move frames. */
 13 export class MappingEditorRuntime {
 14   private disposed = false;
 15   private syncing = false;
 16   private settling = false;
 17   private navigating = false;
 18   private dirty = false;
 19   private pendingProjection = false;
 20   private checkpoint = '';
 21   private unsubscribes: (() => void)[] = [];
 22   private projected = new Map<string, TLShapePartial<MappingShape>>();
 23   constructor(readonly editor: Editor, readonly controller: MappingDocumentController, readonly selectionOwnership = new NativeSelectionOwnership()) {
 24     this.hydrate();
 25     this.unsubscribes.push(controller.attachEditorDriver({ settle: () => { if (!this.settling) { this.editor.complete(); this.settle(true, false); } }, undo: redo => this.undo(redo) }));
 26     let previous = controller.getSnapshot();
 27     this.unsubscribes.push(controller.subscribe(() => {
 28       const next = controller.getSnapshot();
 29       if (next.canvas.selection !== previous.canvas.selection && !this.settling && !this.navigating)
 30         this.selectionOwnership.claim('application');
 31       const relevant = next.canvasRevisionId !== previous.canvasRevisionId || next.document !== previous.document
 32         || next.canvas.display !== previous.canvas.display || next.canvas.diagramViews !== previous.canvas.diagramViews
 33         || next.canvas.selection !== previous.canvas.selection || next.cell !== previous.cell;
 34       previous = next;
 35       if (relevant) this.publish();
 36     }));
 37     // This synchronous observer distinguishes history navigation from an ordinary
 38     // shape edit before another API request can observe the old checkpoint.
 39     this.unsubscribes.push(editor.sideEffects.registerAfterChangeHandler('document', (_before, after) => {
 40       const id = after.meta.mappingCheckpoint;
 41       if (this.syncing || typeof id !== 'string' || id === controller.getSnapshot().canvasRevisionId) return;
 42       this.navigating = true;
 43       try { controller.restoreEditorCheckpoint(id); this.checkpoint = id; this.publish(false); }
 44       finally { this.navigating = false; }
 45     }));
 46     this.unsubscribes.push(editor.store.listen(({ changes }) => {
 47       if (this.syncing) return;
 48       if (Object.values(changes.added).some(record => record.typeName === 'shape')
 49         || Object.values(changes.removed).some(record => record.typeName === 'shape')
 50         || Object.values(changes.updated).some(([before, after]) => after.typeName === 'shape'
 51           || after.typeName === 'instance_page_state' && before.typeName === 'instance_page_state'
 52             && after.selectedShapeIds.join() !== before.selectedShapeIds.join())) this.dirty = true;
 53     }, { scope: 'all' }));
 54     const tick = () => {
 55       if (editor.inputs.getIsPointing() || editor.inputs.getIsDragging() || editor.inputs.getIsPinching()) return;
 56       // Finish native geometry first, but never overwrite a pending domain selection.
 57       if (this.dirty) this.settle(false, !this.pendingProjection && this.selectionOwnership.captureSelection);
 58       if (this.pendingProjection) this.publish();
 59     };
 60     editor.on('tick', tick);
 61     this.unsubscribes.push(() => { editor.off('tick', tick); });
 62   }
 63   private setCheckpoint(id: string) {
 64     const document = this.editor.getDocumentSettings();
 65     // updateDocumentSettings intentionally ignores history in the SDK. This
 66     // application checkpoint is document data and must share the shape diff.
 67     this.editor.store.put([{ ...document, meta: { ...document.meta, mappingCheckpoint: id } }]);
 68   }
 69   /** Replay only checkpoint references. Old shape geometry is materialized lazily
 70    * on navigation, so startup does not reparse every historical ASCII document. */
 71   private hydrate() {
 72     this.syncing = true;
 73     try {
 74       const record = this.controller.editorHistory();
 75       const sequence = [...record.past, record.headId, ...[...record.future].reverse()];
 76       this.editor.run(() => this.setCheckpoint(sequence[0]), { history: 'ignore' });
 77       this.editor.clearHistory();
 78       for (const id of sequence.slice(1)) {
 79         this.editor.markHistoryStoppingPoint('mapping checkpoint');
 80         this.setCheckpoint(id);
 81       }
 82       for (let i = 0; i < record.future.length; i++) this.editor.undo();
 83       this.checkpoint = record.headId;
 84       this.writeShapes(false);
 85     } finally { this.syncing = false; }
 86   }
 87   private writeShapes(record: boolean) {
 88     const shapes = projectMappingShapes(this.controller.getSnapshot()).map(shape => ({ ...shape, parentId: shape.parentId ?? this.editor.getCurrentPageId() }));
 89     const ids = new Set(shapes.map(shape => shape.id));
 90     this.editor.run(() => {
 91       const removed = this.editor.getCurrentPageShapes().filter(shape => shape.type === 'mapping-box' && !ids.has(shape.id));
 92       this.editor.deleteShapes(removed.map(shape => shape.id));
 93       const create: TLShapePartial<MappingShape>[] = [], update: TLShapePartial<MappingShape>[] = [];
 94       for (const shape of shapes) {
 95         const current = this.editor.getShape<MappingShape>(shape.id);
 96         if (!current) create.push(shape);
 97         else if (current.parentId !== (shape.parentId ?? this.editor.getCurrentPageId()) || current.x !== shape.x || current.y !== shape.y || current.isLocked !== shape.isLocked
 98           || JSON.stringify(current.props) !== JSON.stringify(shape.props)) update.push(shape);
 99       }
100       if (create.length) this.editor.createShapes(create);
101       if (update.length) this.editor.updateShapes(update);
102       // Edges stay above diagram shapes, including after creation and history replay.
103       const edgeIds = shapes.filter(shape => shape.props?.kind === 'arrow').map(shape => shape.id);
104       this.editor.run(() => this.editor.bringToFront([...edgeIds, ...this.editor.getCurrentPageShapes().filter(shape => shape.type === 'mapping-box' && (shape as MappingShape).props.kind === 'diagram-side-panel').map(shape => shape.id)]), { ignoreShapeLock: true });
105       this.projected = new Map(shapes.map(shape => [shape.props!.nodeId!, shape]));
106       const selected = this.selectedShapeIds();
107       const native = this.editor.getSelectedShapeIds();
108       if (native.length !== selected.length || selected.some(id => !native.includes(id))) this.editor.setSelectedShapes(selected);
109     }, { history: record ? 'record' : 'ignore' });
110   }
111   private selectedShapeIds() {
112     this.selectionOwnership.dragDiagramIds = this.selectionOwnership.dragDiagramIds.filter(id => this.editor.getShape(mappingShapeId(id)));
113     return [...new Set([...selectedDiagramIds(this.controller.getSnapshot().canvas.selection), ...this.selectionOwnership.dragDiagramIds])]
114       .map(mappingShapeId).filter(id => this.editor.getShape(id));
115   }
116   private publish(record = true) {
117     if (this.syncing || this.disposed) return;
118     this.syncing = true;
119     try {
120       const id = this.controller.getSnapshot().canvasRevisionId;
121       const changed = id !== this.checkpoint;
122       if (!changed && this.editor.inputs.getIsPointing()) { this.pendingProjection = true; return; }
123       this.pendingProjection = false;
124       if (changed && record && !this.settling && !this.navigating) this.editor.markHistoryStoppingPoint('mapping command');
125       this.editor.run(() => {
126         this.writeShapes(changed && record && !this.navigating);
127         this.setCheckpoint(id);
128       }, { history: changed && record && !this.navigating ? 'record' : 'ignore' });
129       this.checkpoint = id;
130     } finally { this.syncing = false; }
131   }
132   settle(force = false, captureSelection = this.selectionOwnership.captureSelection) {
133     if (this.syncing || this.settling || this.navigating || this.disposed) return;
134     if (!force && this.editor.inputs.getIsPointing()) return;
135     this.dirty = false;
136     this.settling = true;
137     try {
138       let selected = this.editor.getSelectedShapes().filter(shape => shape.type === 'mapping-box' && shape.props.kind === 'diagram')
139         .map(shape => (shape as MappingShape).props.nodeId);
140       const snapshot = this.controller.getSnapshot();
141       const cell = snapshot.cell?.width ? snapshot.cell : DEFAULT_CELL;
142       const boxes = flattenGrid(resolveScene(snapshot.document.scene));
143       const nativeShapes = this.editor.getCurrentPageShapes();
144       const clones = nativeShapes.filter(shape => shape.type === 'mapping-box' && shape.id !== mappingShapeId(shape.props.nodeId));
145       const unsupportedClone = clones.some(shape => shape.type === 'mapping-box' && (shape.props.kind !== 'diagram'
146         || !boxes.some(box => box.children.some(child => `grid:${child.box.id}` === shape.props.nodeId))));
147       if (unsupportedClone) { this.editor.deleteShapes(clones.map(shape => shape.id)); selected = []; }
148       const moves: DiagramOperation[] = [];
149       let display = snapshot.canvas.display;
150       for (const shape of this.editor.getCurrentPageShapes()) {
151         if (shape.type !== 'mapping-box') continue;
152         const previous = this.projected.get(shape.props.nodeId);
153         if (!previous) continue;
154         if (shape.id !== mappingShapeId(shape.props.nodeId)) {
155           if (shape.props.kind === 'diagram') {
156             const id = `copy-${crypto.randomUUID()}`, point = this.editor.getShapePageBounds(shape)!;
157             moves.push({ method: 'duplicate-instance', sourceNodeId: shape.props.nodeId, id,
158               position: { column: Math.max(0, Math.round(point.x / cell.width)), row: Math.max(0, Math.round(point.y / cell.height)) } });
159             if (this.editor.getSelectedShapeIds().includes(shape.id)) selected = selected.map(nodeId => nodeId === shape.props.nodeId ? `grid:${id}` : nodeId);
160           } else {
161             // Pane and group copies need semantic ownership remapping. Until such
162             // a command exists, cancel these temporary native clones.
163             this.editor.deleteShapes([shape.id]);
164           }
165           continue;
166         }
167         if (shape.props.nodeId.startsWith('grid:')) {
168           if (shape.x === previous.x && shape.y === previous.y) continue;
169           const id = shape.props.nodeId.slice(5), parent = boxes.find(box => box.children.some(child => child.box.id === id));
170           if (!parent && shape.props.kind !== 'diagram') continue;
171           const point = this.editor.getShapePageBounds(shape)!;
172           moves.push({ method: 'move', nodeId: shape.props.nodeId, position: {
173             column: Math.max(0, Math.round(point.x / cell.width)),
174             row: Math.max(0, Math.round(point.y / cell.height)) } });
175         } else {
176           const node = display.nodes[shape.props.nodeId.slice(9)];
177           if (!node) continue;
178           if (shape.x === previous.x && shape.y === previous.y && shape.props.w === previous.props?.w && shape.props.h === previous.props?.h) continue;
179           display = updateDisplayGeometry(display, node.id, { position: { x: shape.x, y: shape.y }, bounds: { width: shape.props.w, height: shape.props.h } });
180           display = { ...display, nodes: { ...display.nodes, [node.id]: { ...display.nodes[node.id],
181             geometryPolicy: { placement: 'manual', sizing: shape.props.w !== previous.props?.w || shape.props.h !== previous.props?.h ? 'fixed' : node.geometryPolicy.sizing },
182             ...(node.kind === 'conversation' && node.expansion === 'collapsed' ? { canvasAnchor: { x: shape.x, y: shape.y } } : {}) } } };
183         }
184       }
185       const canvas = display === snapshot.canvas.display ? snapshot.canvas : { ...snapshot.canvas, display };
186       // Native selection only enables dragging. Content membership changes through
187       // explicit application gestures (node selection, marquee, whole-diagram double-click).
188       if (captureSelection) this.selectionOwnership.dragDiagramIds = selected.filter(id => !selectedDiagramIds(canvas.selection).includes(id));
189       if (moves.length || canvas !== snapshot.canvas) this.controller.commitEditorGesture(moves, canvas);
190       if (!captureSelection) {
191         const ids = this.selectedShapeIds();
192         this.editor.run(() => this.editor.setSelectedShapes(ids), { history: 'ignore' });
193       }
194     } finally { this.settling = false; }
195   }
196   undo(redo = false) {
197     this.editor.complete(); this.settle();
198     const history = this.controller.editorHistory();
199     if ((redo ? history.redoTransactionId : history.undoTransactionId))
200       throw new Error('Use workspace undo/redo for a canvas transfer.');
201     if (redo) this.editor.redo(); else this.editor.undo();
202   }
203   dispose() {
204     this.editor.complete(); this.settle(); this.disposed = true;
205     this.unsubscribes.splice(0).reverse().forEach(dispose => dispose());
206   }
207 }

